/* Styles communs des titres */
h1, h2 {
  color: navy;
}

body {
  background: #f8fafc;
}

.boite {
  box-sizing: border-box;
  width: 300px;
  padding: 20px;
  border: 5px solid #333;
}

.zone {
  box-sizing: border-box;
  width: 100%;
  max-width: 640px;
  padding: 24px;
  border: 8px solid navy;
  margin: 0 auto;
}

span {
  display: block;
}

a {
  display: inline-block;
  padding: 6px 12px;
}

.cache {
  display: none;
}

.badge {
  display: inline-block;
  width: 80px;
  text-align: center;
}

.menu a {
  display: inline-block;
  padding: 10px 18px;
  background: #1e293b;
  color: white;
  text-decoration: none;
}

.parent {
  position: relative;
}

.badge {
  position: absolute;
  top: 8px;
  right: 8px;
}

header {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  z-index: 100;
}

body {
  padding-top: 70px;
}
